import itertools
import random

def is_triangle(a, b, c):
    return a + b > c and a + c > b and b + c > a

def get_max_s(n, max_val=10):
    max_s = 0
    for _ in range(5000):
        triangles = []
        for _ in range(n):
            while True:
                a = random.randint(1, max_val)
                b = random.randint(1, max_val)
                c = random.randint(1, max_val)
                if is_triangle(a, b, c):
                    triangles.append((a, b, c))
                    break

        gs = sorted([t[0] for t in triangles], reverse=True)
        ps = sorted([t[1] for t in triangles], reverse=True)
        os = sorted([t[2] for t in triangles], reverse=True)

        s_count = 0
        for i in range(n):
            if not is_triangle(gs[i], ps[i], os[i]):
                s_count += 1
        if s_count > max_s:
            max_s = s_count
    return max_s

for n in range(2, 8):
    print(f"n={n}, max_s={get_max_s(n, 20)}")

