def find_max_s_brute_force(n, max_val=10):
    triangles = []
    for a in range(1, max_val + 1):
        for b in range(1, max_val + 1):
            for c in range(1, max_val + 1):
                if is_triangle(a, b, c):
                    triangles.append((a, b, c))

    max_s = 0
    best_triangles = None

    # This is still a lot of combinations.
    # Let's try only picking triangles with side lengths up to 10.
    # There are only a few such triangles.
    for combo in itertools.combinations(triangles, n):
        gs = sorted([t[0] for t in combo], reverse=True)
        ps = sorted([t[1] for t in combo], reverse=True)
        os = sorted([t[2] for t in combo], reverse=True)

        s_count = 0
        for i in range(n):
            if not is_triangle(gs[i], ps[i], os[i]):
                s_count += 1
        if s_count > max_s:
            max_s = s_count
            best_triangles = combo

    return max_s, best_triangles

