import random

def find_max_s_sampling(n, max_val=15, trials=100000):
    triangles = []
    for a in range(1, max_val + 1):
        for b in range(1, max_val + 1):
            for c in range(1, max_val + 1):
                if is_triangle(a, b, c):
                    triangles.append((a, b, c))

    max_s = 0
    best_triangles = None
    for _ in range(trials):
        # We can have duplicate triangles
        current_triangles = [random.choice(triangles) for _ in range(n)]
        gs = sorted([t[0] for t in current_triangles], reverse=True)
        ps = sorted([t[1] for t in current_triangles], reverse=True)
        os = sorted([t[2] for t in current_triangles], reverse=True)

        s_count = 0
        for i in range(n):
            if not is_triangle(gs[i], ps[i], os[i]):
                s_count += 1
        if s_count > max_s:
            max_s = s_count
            best_triangles = current_triangles
    return max_s, best_triangles

